export type Cell = [number, number];

const NEIGHBOUR_COUNT_THAT_SUSTAINS_LIFE = 2;

function isNeighbour([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  const sameCell = x === otherX && y === otherY;
  return !sameCell && Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
}

function livingNeighbourCount(cell: Cell, livingCells: Cell[]): number {
  return livingCells.filter((other) => isNeighbour(cell, other)).length;
}

export function nextGeneration(cells: Cell[]): Cell[] {
  return cells.filter(
    (cell) => livingNeighbourCount(cell, cells) === NEIGHBOUR_COUNT_THAT_SUSTAINS_LIFE,
  );
}

